#!/usr/bin/env bash
# GENERATED by plugin-cursor/scripts/compose.sh — edit plugin/ then re-compose
# Copyright (c) 2024-2026 H3Tech Inc. All rights reserved. PROPRIETARY.
#
# Hook: PostToolUseFailure  (async)
# Purpose: Ship tool-failure telemetry to the control-plane outbox so
# failed tool calls appear in /reliability analytics. Mirrors the
# PostToolUse synaptory-activity-ping.sh pattern; reuses activity_parser.py.
#
# PostToolUseFailure stdin (Claude Code):
#   {"tool_name": "…", "tool_input": {…}, "error": "…",
#    "session_id": "…", "cwd": "…",
#    "hook_event_name": "PostToolUseFailure"}

set -u

_HOOK_ROOT="${PLUGIN_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
# shellcheck source=lib/resolve-python.sh
source "${_HOOK_ROOT}/hooks/lib/resolve-python.sh" 2>/dev/null || exit 0
_py="${SYNAPTORY_PYTHON:-python3}"

SUITE_DIR="${CLAUDE_PROJECT_DIR:-}/.synaptory"
if [ -z "${CLAUDE_PROJECT_DIR:-}" ] || [ ! -d "$SUITE_DIR" ]; then
  exit 0
fi

cli=$("${_HOOK_ROOT}/hooks/_resolve-cli.sh" 2>/dev/null || true)
if [[ -z "$cli" ]] || [[ ! -x "$cli" ]]; then
  exit 0
fi

ACTIVITY_PARSER="${_HOOK_ROOT}/hooks/lib/activity_parser.py"
if [ ! -f "$ACTIVITY_PARSER" ]; then
  exit 0
fi

INPUT="$(cat 2>/dev/null || true)"

# Reuse the activity parser to get (tool_name, summary).
PARSED=$(printf '%s' "$INPUT" | "$_py" "$ACTIVITY_PARSER" 2>/dev/null || true)
TOOL_NAME=$(printf '%s' "$PARSED" | sed -n '1p')
SUMMARY=$(printf '%s' "$PARSED" | sed -n '2p')

# Extract error message and append to summary.
ERROR_MSG=$(printf '%s' "$INPUT" | "$_py" -c "
import sys, json
try:
    d = json.load(sys.stdin)
    print(str(d.get('error') or '')[:120])
except Exception:
    print('')
" 2>/dev/null || true)

if [ -z "$TOOL_NAME" ]; then
  TOOL_NAME="unknown"
fi
COMBINED="${SUMMARY:-${TOOL_NAME} failed}"
if [ -n "$ERROR_MSG" ]; then
  COMBINED="${COMBINED} — ${ERROR_MSG}"
fi

(
  "$cli" telemetry activity \
    --kind tool_failure \
    --tool "$TOOL_NAME" \
    --summary "$COMBINED" \
    >/dev/null 2>&1
) &
disown 2>/dev/null || true

exit 0
